void reserve( int newCapacity )
{
    if( newCapacity < theSize )
        return;

    Object *newArray = new Object[ newCapacity ];
    for( int k = 0; k < theSize; ++k )
        newArray[ k ] = std::move( objects[ k ] );

    theCapacity = newCapacity;
    std::swap( objects, newArray );
    delete [] newArray;
}
